//! End-to-end decoding tests against fixtures generated by Node.js `zlib`.
//!
//! The fixtures are hex strings in `streams/fixtures.rs`; they were produced by
//! an independent encoder so a symmetric bug cannot hide behind them.

#[path = "streams/fixtures.rs"]
mod fixtures;

use ida_inflate::{InflateError, decompress_gzip, decompress_raw, decompress_zlib};

/// Decodes a lowercase hex fixture into bytes.
fn hex(text: &str) -> Vec<u8> {
    assert!(text.len() % 2 == 0, "hex fixtures must have an even length");
    (0..text.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&text[index..index + 2], 16).expect("fixture must be lowercase hex"))
        .collect()
}

/// Plaintext of [`fixtures::ZLIB_SHORT`].
fn short_text() -> Vec<u8> {
    "hello world ".repeat(50).into_bytes()
}

/// Plaintext of [`fixtures::ZLIB_LONG`].
fn long_text() -> Vec<u8> {
    "the quick brown fox jumps over the lazy dog\n".repeat(1000).into_bytes()
}

/// Plaintext of [`fixtures::GZIP_MULTI`].
fn multi_block_text() -> Vec<u8> {
    "payload-block-0123456789\n".repeat(5000).into_bytes()
}

/// Plaintext of [`fixtures::GZIP_NAMED`] and [`fixtures::GZIP_FLAGS`].
fn named_text() -> Vec<u8> {
    "gzip named payload ".repeat(64).into_bytes()
}

/// Reproduces the pseudo-random generator used to build the stored fixtures.
fn pseudo_random(length: usize) -> Vec<u8> {
    let mut state: u32 = 12_345;
    (0..length)
        .map(|_| {
            state = state.wrapping_mul(1_103_515_245).wrapping_add(12_345);
            (state >> 16) as u8
        })
        .collect()
}

#[test]
fn zlib_short_text() {
    let stream = hex(fixtures::ZLIB_SHORT);
    assert_eq!(decompress_zlib(&stream, 600).expect("short zlib stream decodes"), short_text());
    // The raw payload decodes the same bytes and ignores the Adler-32 trailer.
    assert_eq!(decompress_raw(&stream[2..], 600).expect("deflate payload decodes"), short_text());
}

#[test]
fn zlib_long_repetitive_text() {
    let output = decompress_zlib(&hex(fixtures::ZLIB_LONG), 44_000).expect("long zlib stream decodes");
    assert_eq!(output.len(), 44_000);
    assert_eq!(output, long_text());
}

#[test]
fn raw_incompressible_bytes() {
    let stream = hex(fixtures::RAW_RANDOM);
    assert_eq!((stream[0] >> 1) & 3, 0, "incompressible fixture must use stored blocks");
    assert_eq!(decompress_raw(&stream, 4096).expect("random payload decodes"), pseudo_random(4096));
}

#[test]
fn zlib_stored_block() {
    let stream = hex(fixtures::ZLIB_STORED);
    assert_eq!((stream[2] >> 1) & 3, 0, "level 0 fixture must use a stored block");
    assert_eq!(decompress_zlib(&stream, 1000).expect("stored zlib stream decodes"), pseudo_random(1000));
}

#[test]
fn empty_streams() {
    assert!(decompress_raw(&hex(fixtures::RAW_EMPTY), 0).expect("empty raw stream decodes").is_empty());
    assert!(decompress_zlib(&hex(fixtures::ZLIB_EMPTY), 0).expect("empty zlib stream decodes").is_empty());
    assert!(decompress_gzip(&hex(fixtures::GZIP_EMPTY), 0).expect("empty gzip stream decodes").is_empty());
}

#[test]
fn gzip_multi_block() {
    let output = decompress_gzip(&hex(fixtures::GZIP_MULTI), 125_000).expect("gzip stream decodes");
    assert_eq!(output, multi_block_text());
}

#[test]
fn fixed_huffman_block() {
    let stream = hex(fixtures::RAW_HELLO);
    assert_eq!((stream[0] >> 1) & 3, 1, "fixture must use a fixed Huffman block");
    assert_eq!(decompress_raw(&stream, 5).expect("fixed block decodes"), b"hello".to_vec());
}

#[test]
fn gzip_with_optional_header_fields() {
    // FEXTRA, FNAME, FCOMMENT and FHCRC are present in this header.
    let flagged = decompress_gzip(&hex(fixtures::GZIP_FLAGS), 1216).expect("flagged gzip header is parsed");
    assert_eq!(flagged, named_text());
    assert_eq!(decompress_gzip(&hex(fixtures::GZIP_NAMED), 1216).expect("plain gzip decodes"), named_text());

    // The two-byte header checksum sits after the header strings at offset 36.
    let mut broken = hex(fixtures::GZIP_FLAGS);
    broken[36] ^= 0x01;
    assert_eq!(decompress_gzip(&broken, 1216), Err(InflateError::Corrupt("gzip header checksum mismatch")));
}

#[test]
fn truncated_inputs() {
    let stream = hex(fixtures::ZLIB_SHORT);
    let cut = stream.len() / 2;
    assert_eq!(decompress_zlib(&stream[..cut], 600), Err(InflateError::Truncated));
    assert_eq!(decompress_zlib(&stream[..stream.len() - 5], 600), Err(InflateError::Truncated));
    assert_eq!(decompress_zlib(&stream[..stream.len() - 4], 600), Err(InflateError::Truncated));
    assert_eq!(decompress_zlib(&stream[..2], 600), Err(InflateError::Truncated));
    assert_eq!(decompress_raw(&[], 16), Err(InflateError::Truncated));
    let hello = hex(fixtures::RAW_HELLO);
    assert_eq!(decompress_raw(&hello[..3], 16), Err(InflateError::Truncated));
    let gzip = hex(fixtures::GZIP_MULTI);
    assert_eq!(decompress_gzip(&gzip[..8], 16), Err(InflateError::Truncated));
}

#[test]
fn corrupted_checksums() {
    let mut stream = hex(fixtures::ZLIB_SHORT);
    let last = stream.len() - 1;
    stream[last] ^= 0x01;
    assert_eq!(decompress_zlib(&stream, 600), Err(InflateError::Corrupt("zlib Adler-32 mismatch")));

    let mut stream = hex(fixtures::GZIP_MULTI);
    let crc = stream.len() - 8;
    stream[crc] ^= 0x01;
    assert_eq!(decompress_gzip(&stream, 125_000), Err(InflateError::Corrupt("gzip CRC-32 mismatch")));

    let mut stream = hex(fixtures::GZIP_MULTI);
    let size = stream.len() - 1;
    stream[size] ^= 0x01;
    assert_eq!(decompress_gzip(&stream, 125_000), Err(InflateError::Corrupt("gzip length mismatch")));
}

#[test]
fn limit_is_enforced() {
    let stream = hex(fixtures::ZLIB_SHORT);
    assert_eq!(decompress_zlib(&stream, 599), Err(InflateError::LimitExceeded));
    assert_eq!(decompress_zlib(&stream, 600).expect("exact limit decodes").len(), 600);

    assert_eq!(decompress_raw(&hex(fixtures::RAW_RANDOM), 4095), Err(InflateError::LimitExceeded));
    assert_eq!(decompress_gzip(&hex(fixtures::GZIP_MULTI), 124_999), Err(InflateError::LimitExceeded));
    assert_eq!(decompress_gzip(&hex(fixtures::GZIP_NAMED), 0), Err(InflateError::LimitExceeded));
}

#[test]
fn trailing_bytes_are_ignored() {
    let mut stream = hex(fixtures::RAW_HELLO);
    stream.extend_from_slice(b"trailing junk");
    assert_eq!(decompress_raw(&stream, 5).expect("raw trailing bytes are ignored"), b"hello".to_vec());

    let mut stream = hex(fixtures::ZLIB_SHORT);
    stream.extend_from_slice(&[0, 1, 2, 3]);
    assert_eq!(decompress_zlib(&stream, 600).expect("zlib trailing bytes are ignored"), short_text());

    let mut stream = hex(fixtures::GZIP_MULTI);
    stream.extend_from_slice(&[0xff; 8]);
    assert_eq!(decompress_gzip(&stream, 125_000).expect("gzip trailing bytes are ignored"), multi_block_text());
}

#[test]
fn invalid_streams_are_rejected() {
    assert_eq!(decompress_raw(&[0x07], 16), Err(InflateError::Corrupt("reserved block type")));
    assert_eq!(decompress_gzip(b"not gzip data", 16), Err(InflateError::Corrupt("not a gzip stream")));
    assert_eq!(decompress_zlib(&[0x78, 0x9d], 16), Err(InflateError::Corrupt("zlib header check failed")));
    assert_eq!(decompress_zlib(&[0x88, 0x00], 16), Err(InflateError::Corrupt("zlib window size exceeds 32 KiB")));
    assert_eq!(
        decompress_zlib(&[0x78, 0xbb, 0, 0, 0, 0], 16),
        Err(InflateError::Corrupt("zlib preset dictionary is not supported"))
    );

    let mut stream = hex(fixtures::GZIP_EMPTY);
    stream[3] |= 0x20;
    assert_eq!(decompress_gzip(&stream, 0), Err(InflateError::Corrupt("reserved gzip header flags are set")));

    let mut stream = hex(fixtures::GZIP_EMPTY);
    stream[2] = 0x09;
    assert_eq!(decompress_gzip(&stream, 0), Err(InflateError::Corrupt("unsupported gzip compression method")));
}

#[test]
fn stored_block_is_copied_and_validated() {
    let stream = hex(fixtures::RAW_STORED_ABC);
    assert_eq!(decompress_raw(&stream, 3).expect("stored block decodes"), b"abc".to_vec());

    let mut broken = stream.clone();
    broken[4] ^= 0xff;
    assert_eq!(decompress_raw(&broken, 3), Err(InflateError::Corrupt("stored block length check failed")));
}

#[test]
fn distance_before_output_is_rejected() {
    assert_eq!(
        decompress_raw(&hex(fixtures::RAW_BAD_DISTANCE), 16),
        Err(InflateError::Corrupt("distance beyond the start of the output"))
    );
}

#[test]
fn random_bytes_never_panic() {
    let mut state: u32 = 0x1234_5678;
    for length in 0..96 {
        let mut bytes = Vec::with_capacity(length);
        for _ in 0..length {
            state ^= state << 13;
            state ^= state >> 17;
            state ^= state << 5;
            bytes.push(state as u8);
        }
        let _ = decompress_raw(&bytes, 65_536);
        let _ = decompress_zlib(&bytes, 65_536);
        let _ = decompress_gzip(&bytes, 65_536);
    }
}

#[test]
fn error_rendering() {
    fn assert_error<T: std::error::Error>() {}
    assert_error::<InflateError>();

    assert_eq!(InflateError::Truncated.to_string(), "truncated compressed stream");
    assert_eq!(InflateError::LimitExceeded.to_string(), "decoded output exceeds the limit");
    assert_eq!(InflateError::Corrupt("bad table").to_string(), "corrupt compressed stream: bad table");
}
